G=load(); print(sorted(G))
for n in (1,2):
    a=np.array(G[f'Demo pair {n} input']); b=np.array(G[f'Demo pair {n} output'])
    col=[c for c in sorted(set(a.flatten().tolist())-{0,a[0,0]})]
    # normalized shapes of each color in right region
    def normshape(c):
        rr,cc=np.where(a==c)
        tr=min(rr.tolist()); tl=min(cc.tolist())
        return frozenset((int(r-tr),int(cc2-tl)) for r,cc2 in zip(rr.tolist(),cc.tolist()))
