    for oc in ob:
        rr,cc=np.where(b==oc)
        tr=min(rr.tolist()); tl=min(cc.tolist())
        omask=frozenset((int(r-tr),int(c2-tl)) for r,c2 in zip(rr.tolist(),cc.tolist()))
        srcs=[c for c,s in S.items() if s==omask]
        print('   out color',oc,'shape size',len(omask),'matches input shape color(s)',srcs)

