def norm(cells):
    mr=min(r for r,_ in cells); mc=min(c for _,c in cells)
    return frozenset((int(r-mr),int(c-mc)) for r,c in cells)
def f(a):
    a=np.array(a); fr=int(a[0,0]); h,w=a.shape
    left_cols=w//2
    L=a[:,:left_cols]; R=a[:,left_cols:]
    # candidate shapes from right: nonzero non-fr cells grouped per color, dedupe by norm pattern
    shapes={}
    for c in sorted(set(R.flatten().tolist())-{0,fr}):
        for cp in comps(R==c):
            n_=norm(cp)
            if n_ not in shapes or len(shapes[n_])==len(cp): shapes[n_]=c
    out=L.copy()
    # slots: zero cells in L that aren't the frame (frame!=0? careful: bg=0, frame color fr may be 0)
    z=(L==0)&(L!=fr)
    for cp in comps(z):
        n_=norm(cp)
        if n_ in shapes:
            for r,c in cp:
                out[r][c]=shapes[n_]
    return out.tolist()
